{
	return {float4::load(x), float4::load(y), float4::load(z)};
}

void vec3f::store(float *x, float *y, float *z) const
{
	this->x.store(x);
	this->y.store(y);
	this->z.store(z);
}

vec3f vec3f::operator-(int other) const
{
	return {x - other, y - other, z - other};
}

