float4 vec3f::dot(vec3f other) const
{
	return x * other.x + y * other.y + z * other.z;
}
vec3f vec3f::cross(vec3f other) const
{
	return {y * other.z - z * other.y, z * other.x - x * other.z,
			x * other.y - y * other.x};
}
float4 vec3f::length2() const { return dot(*this); }
float4 vec3f::length() const { return length2().sqrt(); }

