// definitions can live here instead of in the header.  The shift count is
// constrained to [0, 31] by static_assert, so every valid instantiation is
// provided.
template <int bits> uint4 uint4::shl() const
{
	static_assert(bits >= 0 && bits < 32,
				  "uint4 shift count must be in [0, 31]");
	return {VEC_SHL_U(v, bits)};
}
template <int bits> uint4 uint4::shr() const
{
	static_assert(bits >= 0 && bits < 32,
				  "uint4 shift count must be in [0, 31]");
	return {VEC_SHR_U(v, bits)};
}

